# -*- coding: utf-8 -*-
# ICQ icons for JewAIXP. Two sizes: small (8x8) and normal (16x16).
# Files auto-generated by _icq_resize.py.

import os

try:
    import tkinter as tk
except ImportError:
    import Tkinter as tk


HERE = os.path.dirname(os.path.abspath(__file__))


def _p(name):
    return os.path.join(HERE, name)


class IconSet(object):
    def __init__(self, master):
        self.master = master
        self.small = {}
        self.normal = {}
        self._load()

    def _load(self):
        def tl(path):
            try:
                return tk.PhotoImage(master=self.master, file=path)
            except Exception:
                return None

        s = self.small
        n = self.normal

        s["online"] = tl(_p("icq_flower_8.gif"))
        s["new"] = tl(_p("icq_new_8.gif")) or s["online"]
        s["offline"] = tl(_p("icq_offline_8.gif")) or s["online"]
        s["red"] = tl(_p("icq_red_8.gif"))

        n["online"] = tl(_p("icq_flower_16.gif")) or tl(_p("icq_flower.gif"))
        n["new"] = tl(_p("icq_new_16.gif")) or n["online"]
        n["offline"] = tl(_p("icq_offline_16.gif")) or n["online"]
        n["red"] = tl(_p("icq_red_16.gif"))

        for k in ("away", "dnd", "unknown"):
            s[k] = s["online"]
            n[k] = n["online"]

    def get(self, kind, size="small"):
        c = self.small if size == "small" else self.normal
        return c.get(kind) or c.get("online")


def demo():
    root = tk.Tk()
    root.title("icons demo")
    root.configure(bg="#c0c0c0")
    ic = IconSet(root)
    for size in ("small", "normal"):
        for kind in ("online", "new", "offline", "red"):
            im = ic.get(kind, size)
            if im:
                lbl = tk.Label(root, image=im, bg="#c0c0c0")
                lbl.image = im
                lbl.pack(side="left", padx=4, pady=4)
        tk.Label(root, text="|", bg="#c0c0c0").pack(side="left")
    root.mainloop()


if __name__ == "__main__":
    demo()